const requests=[];handleAPI=async(req,res)=>{let text='';for await(const chunk of req)text+=chunk;const d=JSON.parse(text);if(d.action?.startsWith('favorites_regions_')){const headers=new Headers(req.headers);headers.set('origin','https://wei304.github.io');const response=await regionHandler(new Request(url+req.url,{method:'POST',headers,body:text}));res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));return;}if(d.action?.startsWith('favorites_')){const result=await favoriteFixture.call(d.action.slice(10),{...d,token:req.headers['x-trip-session']});const {status=200,...out}=result;res.writeHead(status,{'Content-Type':'application/json'}).end(JSON.stringify(out));return;}if(!['status','unlock'].includes(d.action)&&req.headers['x-trip-session']!=='a'.repeat(64)){res.writeHead(401,{'Content-Type':'application/json'}).end(JSON.stringify({error:'locked'}));return;}requests.push(d.action);let out={};if(d.action==='status')out={configured:true};else if(d.action==='unlock')out={session:{token:'a'.repeat(64),expiresAt:Date.now()+3600000}};else if(d.action==='check')out={ok:true};else if(d.action==='rows')out={rows:[...rows.values()].map(({version,...payload})=>({id:payload.id,payload,version}))};else if(d.action==='apply'){const existing=rows.get(d.item.id);if((existing?.version||0)!==d.expected)out={conflict:true,row:{id:existing.id,payload:existing,version:existing.version}};else{const row={...d.item,version:d.expected+1};rows.set(row.id,row);out={conflict:false,row:{id:row.id,payload:d.item,version:row.version}};}}else if(d.action==='apply_batch'){const current=d.entries.map(e=>rows.get(e.item.id));if(d.entries.some((e,n)=>(current[n]?.version||0)!==e.expected))out={conflict:true,rows:current.filter(Boolean).map(r=>({id:r.id,payload:r,version:r.version}))};else{const before=current.map((r,n)=>r||{...d.entries[n].item,deleted:true});const updated=d.entries.map(e=>({...e.item,version:e.expected+1}));updated.forEach(r=>rows.set(r.id,r));out={conflict:false,before,rows:updated.map(r=>({id:r.id,payload:r,version:r.version}))};}}else if(d.action==='exchange_rate')out={quote:{yenPerMyr:40,quoteDate:'2026-11-10',source:'欧洲央行日参考',fetchedAt:new Date().toISOString()}};else if(d.action==='history')out={revisions:[]};else if(d.action==='lock')out={ok:true};else throw Error('unexpected action '+d.action);res.setHeader('Content-Type','application/json');res.end(JSON.stringify(out));};

const fileRows=new Map(),objects=new Map();
const fileHandler=makeFileHandler({rpc:async(action,b)=>{if(action==='check')return b.token==='a'.repeat(64)?{ok:true}:{status:401,error:'locked'};if(action==='list')return {files:[...fileRows.values()].map(f=>({id:f.id,ticketId:f.ticket_id,name:f.original_name,type:f.mime_type,bytes:f.bytes,status:f.status,version:f.version}))};if(action==='route_draft'){const id=crypto.randomUUID();aiDrafts.set(id,{days:b.days,hash:b.scopeHash,entries:b.entries,diff:b.diff,risks:b.risks,status:'preview'});return {draftId:id,expiresAt:new Date(Date.now()+900000).toISOString()};}
 if(action==='reserve'){if(!rows.has(b.ticketId))return {status:404,error:'ticket_not_found'};const f=fileRows.get(b.fileId)||{id:b.fileId,ticket_id:b.ticketId,original_name:b.name,mime_type:b.type,bytes:b.bytes,status:'pending',version:1,storage_path:b.fileId};fileRows.set(f.id,f);return {file:f};}const f=fileRows.get(b.fileId);if(!f)return {status:404,error:'file_not_found'};if(action==='get')return f.status==='ready'?{file:f}:{status:404,error:'file_not_ready'};if(action==='finalize'){f.status='ready';f.version++;return {file:f};}if(['remove','restore'].includes(action)){if(f.version!==b.expected)return {status:409,error:'file_conflict'};f.status=action==='remove'?'removed':'ready';f.version++;return {file:f};}throw Error('bad file action '+action);},put:async(path,bytes,type)=>objects.set(path,{bytes,type}),get:async path=>{const f=objects.get(path);return f?new Response(f.bytes,{headers:{'Content-Type':f.type}}):new Response('',{status:404});}});
handleFiles=async(req,res)=>{const chunks=[];for await(const chunk of req)chunks.push(chunk);const headers=new Headers(req.headers);headers.set('origin','https://wei304.github.io');const request=new Request(url+req.url,{method:'POST',headers,body:Buffer.concat(chunks)});const response=await fileHandler(request);res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));};


let phraseModelCalls=0;let favoriteModelCalls=0;let mockEnabled=false,modelCalls=0,aiWrites=0,budgetVersion=1,normalCny=2,travelCny=10;const aiRequests=new Map(),aiDrafts=new Map();
const aiScope=days=>[...rows.values()].filter(i=>days.includes(i.day)&&!i.deleted&&(!/^(tool-|ledger-|ticket-)/.test(i.id)||i.id.startsWith('tool-leg-'))).map(i=>({id:i.id,payload:JSON.parse(JSON.stringify(i)),version:i.version}));
const aiHash=days=>JSON.stringify(aiScope(days));
const aiHandler=makeAIHandler({enabled:true,rpc:async(action,b)=>{
 if(action.startsWith('phrase_'))return (await favoriteFixture.db.query('select public.phrase_ai_request($1,$2::jsonb) r',[action.slice(7),JSON.stringify(b)])).rows[0].r;
 if(action.startsWith('favorites_')){await favoriteFixture.setTripRows([...rows.values()]);return favoriteFixture.ai(action.slice(10),b);}
 if(b.token!=='a'.repeat(64))return {status:401,error:'locked'};if(action==='status')return {enabled:mockEnabled,policyOn:mockEnabled,dailyRequests:100,dailyTokens:1000000,currency:'CNY',dailyBudgetCny:normalCny,normalBudgetCny:normalCny,travelBudgetCny:travelCny,usedCny:0,todayRequests:0,budgetVersion,budgetDate:'2026-11-11',travelActive:false};if(action==='budget_save'){if(b.expected!==budgetVersion)return {status:409,error:'budget_changed'};budgetVersion++;normalCny=b.normalCny;travelCny=b.travelCny;mockEnabled=b.enabled;return {ok:true,budgetVersion};}
 if(['snapshot','route_snapshot'].includes(action))return {rows:aiScope(b.days),scopeHash:aiHash(b.days),japanToday:'2026-11-11'};
 if(action==='route_draft'){const id=crypto.randomUUID();aiDrafts.set(id,{days:b.days,hash:b.scopeHash,entries:b.entries,diff:b.diff,risks:b.risks,status:'preview'});return {draftId:id,expiresAt:new Date(Date.now()+900000).toISOString()};}
 if(action==='reserve'){const id=crypto.randomUUID();aiRequests.set(id,{days:b.days,hash:b.scopeHash});return {requestId:id};}
 if(action==='finish_no_changes'){assert.equal(b.result.noChanges,true);assert.equal(b.draft,undefined);return {ok:true};}
 if(action==='finish'){const request=aiRequests.get(b.requestId);if(b.draft){const id=crypto.randomUUID();aiDrafts.set(id,{...request,...b.draft,status:'preview'});return {draftId:id,expiresAt:new Date(Date.now()+900000).toISOString()};}return {ok:true};}
 if(action==='fail')return {ok:true};
 const draft=aiDrafts.get(b.draftId);if(!draft)return {status:404,error:'draft_not_found'};
 if(action==='cancel'){draft.status='cancelled';return {ok:true};}
 if(action==='confirm'){if(draft.status==='applied')return draft.response;if(draft.status!=='preview')return {status:409,error:'draft_expired_or_cancelled'};if(draft.hash!==aiHash(draft.days))return {status:409,error:'draft_stale'};const before=draft.entries.map(e=>rows.get(e.item.id)||{...e.item,deleted:true}),updated=draft.entries.map(e=>({...e.item,version:e.expected+1}));updated.forEach(i=>rows.set(i.id,i));aiWrites++;draft.status='applied';draft.response={conflict:false,before,rows:updated.map(i=>({id:i.id,payload:i,version:i.version}))};return draft.response;}
 throw Error('unexpected AI RPC '+action);
},complete:async({input})=>{const data=JSON.parse(input);if(data.version===1&&data.phrase){phraseModelCalls++;assert.deepEqual(Object.keys(data.phrase),['category','zh','ja','kana']);return {content:JSON.stringify({zh:'请给我两份。',ja:'二つお願いします。',kana:'ふたつおねがいします。',sourceLanguage:'zh',targetLanguage:'ja'}),finish:'stop',usage:{total_tokens:100}};}if(data.task==='favorite-classify-v1'){favoriteModelCalls++;assert.ok(!input.includes('private')&&!input.includes('source note'));return {content:JSON.stringify({places:data.USER_DATA.map(p=>({id:p.id,type:'咖啡厅 / 甜品',confidence:'low',days:p.eligibleDays}))}),finish:'stop',usage:{total_tokens:100}};}modelCalls++;assert.ok(!input.includes('Synthetic QA only'),'private notes reached model');const d=JSON.parse(input);let answer=d.task==='translate'?'日文：ありがとうございます。\n假名：ありがとうございます。\n中文：谢谢。':'模拟问答：仅根据已授权行程；未获取天气。';if(d.task==='edit'&&d.prompt==='先核对后澄清')return {content:JSON.stringify({answer:'需要先确认抵达时间。',warnings:[],operations:[]}),finish:'stop',usage:{total_tokens:100}};const operations=d.task==='edit'?[{type:'update',id:'qa-second',changes:{title:'AI测试修改'}}]:d.task==='organize'?[{type:'add',changes:{title:'TXT候选地点',ja:'候補',day:d.days[0],time:'',category:'spot'}}]:[];return {content:JSON.stringify({answer,warnings:['交通与营业时间待核实'],operations}),finish:'stop',usage:{total_tokens:100}};}});
