const sharedSnapshots=new Map();const shareProjection=b=>b.ids.map(id=>rows.get(id)).filter(i=>i&&b.days.includes(i.day)&&['spot','food','shopping'].includes(i.category)&&!i.deleted&&!/^(tool-|ticket-|ledger-|plan-choice-)/.test(i.id));
const shareGuard=b=>JSON.stringify(shareProjection(b));
const shareHandler=makeShareHandler({rpc:async(action,b)=>{if(action==='view'){const share=[...sharedSnapshots.values()].find(s=>s.secret===b.secret&&!s.revoked&&Date.parse(s.expiresAt)>Date.now());return share?{title:share.title,days:share.days,fields:share.fields,items:share.snapshot,createdAt:share.createdAt,expiresAt:share.expiresAt}:{status:404,error:'share_unavailable'};}if(b.token!=='a'.repeat(64))return {status:401,error:'locked'};if(action==='list')return {enabled:true,shares:[...sharedSnapshots.values()].map(({secret,snapshot,...s})=>s)};if(action==='revoke'){const s=sharedSnapshots.get(b.id);s.revoked=true;s.version++;return {ok:true};}const chosen=shareProjection(b);if(chosen.length!==b.ids.length)return {status:422,error:'selection_changed_or_private'};const snapshot=chosen.map(i=>Object.fromEntries([['day',i.day],...b.fields.map(k=>[k,i[k]])]));if(action==='preview')return {snapshot,guard:shareGuard(b)};if(action==='create'){if(b.confirmed!==true||b.guard!==shareGuard(b))return {status:409,error:'share_preview_stale'};if(!sharedSnapshots.has(b.id))sharedSnapshots.set(b.id,{id:b.id,secret:b.secret,title:b.title,days:b.days,fields:b.fields,snapshot,createdAt:new Date().toISOString(),expiresAt:new Date(Date.now()+b.hours*3600000).toISOString(),version:1,revoked:false});return {id:b.id,version:1};}throw Error('unexpected share action');}});
