e.locator('#public-refresh').click();await visitorPage.waitForFunction(()=>document.querySelector('#public-status').textContent.includes('撤销'));assert.equal(await visitorPage.locator('#public-items').textContent(),'');await visitor.close();
stage='five device mixed workload';const devices=[];for(let n=0;n<4;n++){const c=await browser.newContext({viewport:{width:390,height:844}});await c.addInitScript(()=>localStorage.setItem('osaka-2027-v1-shared-session',JSON.stringify({token:'a'.repeat(64),expiresAt:Date.now()+3600000})));const p=await c.newPage();p.on('dialog',d=>d.accept());await p.goto(url);await p.waitForFunction(()=>!document.querySelector('#app-main').hidden);devices.push({c,p});}
