stage='mobile speech feedback';const speechContext=await browser.newContext({viewport:{width:390,height:844}});await speechContext.addInitScript(()=>{localStorage.setItem('osaka-2027-v1-shared-session',JSON.stringify({token:'a'.repeat(64),expiresAt:Date.now()+3600000}));const state={voices:[],calls:[],listeners:[],resumed:0};const synth={getVoices:()=>state.voices,addEventListener:(name,fn)=>{if(name==='voiceschanged')state.listeners.push(fn);},speaking:false,pending:false,paused:false,speak:u=>state.calls.push(u),cancel:()=>{},resume:()=>{state.resumed++;synth.paused=false;}};window.qaSpeech=state;Object.defineProperty(window,'speechSynthesis',{configurable:true,value:synth});Object.defineProperty(window,'SpeechSynthesisUtterance',{configurable:true,value:class{constructor(text){this.text=text;}}});});const speechPage=await speechContext.newPage();await speechPage.goto(url);await speechPage.waitForFunction(()=>!document.querySelector('#app-main').hidden);await openTab(speechPage,'tools');const firstSpeak=speechPage.locator('[data-speak-phrase]').first();assert.equal(await firstSpeak.isDisabled(),false);await speechPage.locator('[data-speech-rate]').first().click();assert.equal(await speechPage.evaluate(()=>qaSpeech.calls.at(-1).rate),.75);await speechPage.locator('#stop-speech').click();await firstSpeak.click();await speechPage.waitForFunction(()=>document.querySelector('#speech-status').textContent.includes('系统自动选择'));assert.equal(await speechPage.evaluate(()=>qaSpeech.calls.at(-1).lang),'ja-JP');assert.equal(await speechPage.evaluate(()=>qaSpeech.calls.at(-1).voice),undefined);await speechPage.evaluate(()=>qaSpeech.calls.at(-1).onstart());await speechPage.waitForFunction(()=>document.querySelector('#speech-status').textContent.includes('已开始'));await speechPage.evaluate(()=>qaSpeech.calls.at(-1).onend());
await speechPage.evaluate(()=>{qaSpeech.voices=[{lang:'ja-JP',name:'Network Japanese',voiceURI:'remote-ja',localService:false},{lang:'ja_JP',name:'Local Japanese',voiceURI:'local-ja',localService:true}];qaSpeech.listeners.forEach(f=>f());});await speechPage.locator('#speech-advanced > summary').click();await speechPage.locator('#refresh-speech').click();await speechPage.locator('#speech-voice').selectOption('remote-ja');assert.equal(await speechPage.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,'speech controls overflow mobile viewport');await firstSpeak.click();assert.match(await speechPage.locator('#speech-status').textContent(),/正在请求/);assert.equal(await speechPage.evaluate(()=>qaSpeech.calls.at(-1).voice.voiceURI),'remote-ja');await speechPage.evaluate(()=>qaSpeech.calls.at(-1).onstart());await speechPage.waitForFunction(()=>document.querySelector('#speech-status').textContent.includes('已开始'));await speechPage.evaluate(()=>qaSpeech.calls.at(-1).onerror({error:'network'}));await speechPage.waitForFunction(()=>document.querySelector('#speech-status').textContent.includes('需要网络'));
await firstSpeak.click();await speechPage.waitForFunction(()=>document.querySelector('#speech-status').textContent.includes('8秒'),{},{timeout:12000});assert.equal(await firstSpeak.textContent(),'朗读');await openTab(speechPage,'settings');await speechPage.locator('#logout').click();await speechPage.waitForFunction(()=>document.querySelector('#app-main').hidden);await speechContext.close();

